"""Search a table-level push with lighter finger forces and a settled end."""
import json,time
from pathlib import Path
import numpy as np
import mw_tool
from scipy.optimize import differential_evolution
s=mw_tool.Session();obj=s.state()['object_pos'].copy();target=s.target_pos.copy()
u=target[:2]-obj[:2];u/=np.linalg.norm(u)
out=Path('/app/output/gentle');out.mkdir(exist_ok=True)
count=0;best=1e3;start=time.time();log=open(out/'results.jsonl','a',buffering=1)

def evaluate(p):
 global count,best
 gain,z,bias,offset,grip,push_steps,rx,ry,rz,retreat_steps=p
 push_steps=int(round(push_steps));retreat_steps=int(round(retreat_steps))
 s.reset();behind=np.r_[obj[:2]-.065*u,.14]
 for goal,limit in [(behind,50),(np.r_[behind[:2],z],70)]:
  for _ in range(limit):
   error=goal-s.state()['tcp'];s.step(np.r_[np.clip(gain*error,-1,1),grip])
   if np.linalg.norm(error)<.003:break
 for _ in range(push_steps):
  st=s.state();delta=target[:2]-st['object_pos'][:2];d=delta/max(np.linalg.norm(delta),1e-8)
  desired=np.r_[st['object_pos'][:2]-offset*d+[bias,0],z]
  s.step(np.r_[np.clip(gain*(desired-st['tcp']),-1,1),grip])
 for _ in range(retreat_steps):s.step([rx,ry,rz,grip])
 errors=[];speeds=[]
 for i in range(140):
  s.step([0,0,0,grip])
  if i>=100:
   errors.append(s.check()['obj_to_target']);speeds.append(np.linalg.norm(s.data.qvel[-6:-3]))
 distance=s.check()['obj_to_target'];mean_distance=float(np.mean(errors));speed=float(np.mean(speeds))
 score=mean_distance+.002*speed
 row={'params':list(map(float,p)),'distance':distance,'mean_distance':mean_distance,'speed':speed,'steps':len(s.actions),'score':score,'success':s.check()['success']}
 log.write(json.dumps(row)+'\n');count+=1
 if score<best:
  best=score
  if s.check()['success']:s.save_trajectory(path=out/'best.npz',meta=row)
  print('BEST',count,row,flush=True)
 if count%200==0:print('progress',count,best,'seconds',time.time()-start,flush=True)
 return score
bounds=[(10,50),(.003,.03),(-.03,.01),(.012,.065),(-1,.5),(45,140),(-.3,.1),(-.5,-.05),(.3,1),(10,35)]
r=differential_evolution(evaluate,bounds,seed=35,popsize=10,maxiter=250,polish=False,tol=1e-5,atol=1e-8)
print('finished',r.fun,r.x,count,flush=True)
