"""Optimize a short rounded-action push with consistent success under rounding."""
import json,time
from pathlib import Path
import numpy as np
import mw_tool
from scipy.optimize import differential_evolution
s=mw_tool.Session();obj=s.state()['object_pos'].copy();target=s.target_pos.copy();u=target[:2]-obj[:2];u/=np.linalg.norm(u)
out=Path('/app/output/robust');out.mkdir(exist_ok=True)
count=0;best=1e3;start=time.time();log=open(out/'results.jsonl','a',buffering=1)

def evaluate(p):
 global count,best
 gain,z,bias,offset,rear,az,stop=p
 s.reset();behind=np.r_[obj[:2]-rear*u,az]
 def step(a):s.step(np.round(a,2))
 for goal,limit in [(behind,35),(np.r_[behind[:2],z],50)]:
  for _ in range(limit):
   error=goal-s.state()['tcp'];step(np.r_[np.clip(gain*error,-1,1),1])
   if np.linalg.norm(error)<.004:break
 for _ in range(100):
  st=s.state();delta=target[:2]-st['object_pos'][:2];d=delta/max(np.linalg.norm(delta),1e-8)
  desired=np.r_[st['object_pos'][:2]-offset*d+[bias,0],z]
  step(np.r_[np.clip(gain*(desired-st['tcp']),-1,1),1])
  if s.check()['obj_to_target']<stop:break
 # Round all controls. Candidate is deliberately simple to serialize and replay.
 for k in range(20):step([0,-.2,.7,1])
 errors=[]
 for i in range(80):
  step([0,0,0,1])
  if i>=60:errors.append(s.check()['obj_to_target'])
 a=np.asarray(s.actions)
 distance=s.check()['obj_to_target'];nominal=float(np.mean(errors))
 # Confirm neighboring action quantization; a decimal grid gives stable
 # serialized actions and checks contact sensitivity without state editing.
 trials=[]
 if nominal<.04:
  for digits in [1,3]:
   s.replay(np.round(a,digits));trials.append(s.check()['obj_to_target'])
 score=max([nominal,*trials])+.000001*len(a)
 row={'params':list(map(float,p)),'distance':distance,'mean_distance':nominal,'rounding_distances':trials,'steps':len(a),'score':score}
 count+=1;log.write(json.dumps(row)+'\n')
 if score<best:
  best=score
  if distance<.05:
   s.save_trajectory(a,path=out/'best.npz',meta=row)
  print('BEST',count,row,flush=True)
 if count%100==0:print('progress',count,best,'seconds',time.time()-start,flush=True)
 return score
bounds=[(25,70),(.002,.02),(-.025,-.008),(.007,.025),(.035,.065),(.12,.17),(.006,.025)]
r=differential_evolution(evaluate,bounds,seed=62,popsize=10,maxiter=250,polish=False,tol=1e-5,atol=1e-8)
print('finished',r.fun,r.x,count,flush=True)
